async function createCloud(){const res=await api('projects',{method:'POST',body:JSON.stringify({state:{...doc.toJSON(),frame}})});cloudId=res.id;revision=res.revision;role='owner';doc.project.id=cloudId;lastSavedState=clone(doc.project);dirty=false;history.replaceState(null,'',`?project=${cloudId}`);$('#save-state').textContent=(BROWSER_MODE?'Saved in this browser':'Saved to project');return res;}
