async function initCloud(){try{session=(await api('session')).user;$('.avatar').textContent=session.email[0].toUpperCase();const query=new URLSearchParams(location.search);const invite=query.get('invite');let id=query.get('project');if(invite){const joined=await api('join',{method:'POST',body:JSON.stringify({token:invite})});id=joined.projectId;history.replaceState(null,'',`?project=${id}`)}if(!id){const list=await api('projects');id=list.projects[0]?.id}if(id){const data=await api('projects/'+id);cloudId=id;revision=data.revision;role=data.role;replaceProject(data.state,{saved:true});lastSavedState=clone(data.state);history.replaceState(null,'',`?project=${id}`);$('#save-state').textContent=role==='reviewer'?'Review access':(BROWSER_MODE?'Saved in this browser':'All changes saved');}else await createCloud();await loadComments();}catch(err){$('#save-state').textContent='Local session · export to keep';if(err.status!==401)toast(err.message,true)}}
