async function importMedia(files){for(const file of files){if(file.size>50*1024*1024){toast(`${file.name}: media is limited to 50 MB per file.`,true);continue;}if(!/^(image|video|audio)\//.test(file.type)){toast(`Unsupported media: ${file.name}`,true);continue;}let asset;if(session){if(!cloudId)await createCloud();$('#save-state').textContent='Uploading '+file.name;asset=await api(`projects/${cloudId}/assets`,{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});}else{asset={id:makeId('asset'),name:file.name,url:URL.createObjectURL(file),type:file.type.split('/')[0],mime:file.type,size:file.size};toast('Media imported into this local session. Keep the original file for relinking.');}const metadata=await mediaMetadata(asset);Object.assign(asset,metadata);mutate('Import '+file.name,()=>{doc.project.assets.push(asset);if(asset.type!=='audio'){const n=doc.addNode('Source',{x:70,y:80+doc.project.nodes.filter(n=>n.type==='Source').length*150,params:{assetId:asset.id}});selected=[n.id];doc.project.viewerNodeId=n.id;}});selectedAsset=asset.id;refresh();toast(`Imported ${file.name}`);}await save();}
